/**
 * SNAKE — Village Edition
 * ----------------------------------------------------------------------------
 * The flagship game of the hub. Every arena is a village generated by the
 * two-pass Wave Function Collapse in ../village.js, so each run looks fresh
 * but always "designed": roads connect, doors face roads, trees cluster.
 *
 * Modes
 *   CLASSIC  walls kill, speed ramps up with every apple
 *   ENDLESS  screen edges wrap around, steady pace, just chill
 *   TIMED    60 seconds, eat as much as possible (golden apples add time)
 *   VILLAGE  houses & trees are solid; clear the apple quota to move on to
 *            a brand-new, denser village
 *
 * Screen: 320x288 (2x the classic handheld's 160x144), 16px tiles,
 * 20x17 playfield + a 16px HUD bar.
 */

import { generateVillage, KIND } from '../village.js';
import { renderVillage, sprites, PAL, TILE } from '../art/village-art.js';
import { drawText } from '../core/pixeltext.js';
import { Particles, Shake, Popups } from '../core/fx.js';
import { getBest, submitScore, bumpStat, storage } from '../core/storage.js';
import { randomSeed, dailySeed, seedLabel } from '../core/rng.js';

const W = 320, H = 288, HUD = 16, COLS = 20, ROWS = 17;
const SPAWN = { x: 5, y: 8 };

const MODES = [
  { id: 'classic', name: 'CLASSIC', desc: ['WALLS BITE. EVERY APPLE', 'MAKES YOU FASTER.'], solid: false, wrap: false, speed: 7, speedUp: 0.22, maxSpeed: 16 },
  { id: 'endless', name: 'ENDLESS', desc: ['EDGES WRAP AROUND.', 'STEADY PACE. RELAX.'], solid: false, wrap: true, speed: 9, speedUp: 0, maxSpeed: 9 },
  { id: 'timed', name: 'TIMED', desc: ['60 SECONDS. GOLDEN', 'APPLES ADD +5 SEC.'], solid: false, wrap: false, speed: 10, speedUp: 0.05, maxSpeed: 12, time: 60 },
  { id: 'village', name: 'VILLAGE', desc: ['DODGE HOUSES & TREES.', 'CLEAR EACH VILLAGE.'], solid: true, wrap: false, speed: 7, speedUp: 0.1, maxSpeed: 13 },
];

const DIRS = { up: [0, -1], down: [0, 1], left: [-1, 0], right: [1, 0] };
const OPP = { up: 'down', down: 'up', left: 'right', right: 'left' };

const C = {
  ink: '#1b2420', bodyInk: '#2a1a08',
  body: '#f2c94c', spot: '#c9802a', shine: '#fff1a8', belly: '#e0a93a',
  hudBg: '#14201a', hudLine: '#9bbc0f', gb0: '#0f380f', gb1: '#306230', gb2: '#8bac0f', gb3: '#9bbc0f',
  white: '#f7f3e3', red: '#ff5964', gold: '#ffd84a', mint: '#b8f28a', dim: '#7c8b7a',
};

export default {
  id: 'snake',
  title: 'Snake',
  width: W,
  height: H,
  create: (api) => new SnakeGame(api),
};

class SnakeGame {
  constructor(api) {
    this.api = api;
    this.ctx = api.ctx;
    this.fx = new Particles(500);
    this.shake = new Shake();
    this.popups = new Popups();
    this.time = 0;
    this.modeIndex = Math.max(0, MODES.findIndex((m) => m.id === storage.get('snake:mode', 'classic')));
    this.state = 'title';
    this.dither = this.#makeDither();
    this.unsub = api.input.on((btn, pressed) => pressed && this.onButton(btn));
    this.#buildTitleMap();
  }

  get mode() { return MODES[this.modeIndex]; }
  /** Tell the shell it may lower the frame rate (battery saver). */
  get lowPower() { return this.state === 'title' || this.state === 'paused' || this.state === 'over'; }

  destroy() { this.unsub?.(); }
  pause() { if (this.state === 'play' || this.state === 'ready') { this.resumeState = this.state; this.state = 'paused'; } }

  // ==========================================================================
  //  Map building
  // ==========================================================================

  #seedFor(tag) {
    return this.api.settings.daily ? dailySeed(`snake:${tag}`) : randomSeed();
  }

  #buildTitleMap() {
    const v = generateVillage({ width: COLS, height: ROWS, seed: this.#seedFor('title'), houses: 1.2 });
    this.map = v;
    this.bg = renderVillage(v);
    this.#indexChimneys();
    this.reveal = 1;
  }

  #buildLevel() {
    const m = this.mode;
    const keepClear = [];
    for (let x = 1; x <= 11; x++) keepClear.push({ x, y: SPAWN.y });
    let best = null;
    for (let attempt = 0; attempt < 8; attempt++) {
      const seed = this.#seedFor(`${m.id}:${this.level}:${attempt}`);
      const v = generateVillage({
        width: COLS, height: ROWS, seed, keepClear,
        solid: m.solid,
        roadDensity: m.solid ? 1 : 0.85,
        houses: 1 + 0.25 * (this.level - 1),
        trees: 0.8 + 0.25 * (this.level - 1),
      });
      const info = this.#analyse(v);
      if (!best || info.reachable > best.info.reachable) best = { v, info };
      if (info.reachable >= COLS * ROWS * 0.55) break;
    }
    this.map = best.v;
    this.solid = best.info.solid;
    this.reach = best.info.reach;
    this.bg = renderVillage(this.map);
    this.seedText = seedLabel(this.map.seed);
    this.#indexChimneys();
  }

  /** Solid cells + flood fill from the spawn to find reachable ground. */
  #analyse(v) {
    const solid = new Uint8Array(COLS * ROWS);
    for (let y = 0; y < ROWS; y++) for (let x = 0; x < COLS; x++) {
      const k = v.kinds[y][x];
      solid[x + y * COLS] = k === KIND.HOUSE || k === KIND.TREE ? 1 : 0;
    }
    const reach = new Uint8Array(COLS * ROWS);
    const stack = [SPAWN.x + SPAWN.y * COLS];
    reach[stack[0]] = 1;
    let count = 0;
    while (stack.length) {
      const i = stack.pop();
      count++;
      const x = i % COLS, y = (i / COLS) | 0;
      for (const [dx, dy] of Object.values(DIRS)) {
        let nx = x + dx, ny = y + dy;
        if (this.mode.wrap) { nx = (nx + COLS) % COLS; ny = (ny + ROWS) % ROWS; }
        if (nx < 0 || ny < 0 || nx >= COLS || ny >= ROWS) continue;
        const j = nx + ny * COLS;
        if (solid[j] || reach[j]) continue;
        reach[j] = 1;
        stack.push(j);
      }
    }
    return { solid, reach, reachable: count };
  }

  #indexChimneys() {
    this.chimneys = [];
    for (let y = 0; y < this.map.height; y++) for (let x = 0; x < this.map.width; x++) {
      if (this.map.tiles[y][x] === 'house_b') this.chimneys.push({ x: x * TILE + 11, y: y * TILE + 1, t: Math.random() });
    }
  }

  // ==========================================================================
  //  Round lifecycle
  // ==========================================================================

  #startRun() {
    storage.set('snake:mode', this.mode.id);
    this.score = 0;
    this.level = 1;
    this.apples = 0;
    this.combo = 0;
    this.newBest = false;
    this.timeLeft = this.mode.time || 0;
    bumpStat('snake:runs');
    this.#startLevel();
  }

  #startLevel() {
    this.#buildLevel();
    this.levelApples = 0;
    this.goal = this.mode.id === 'village' ? 5 + this.level * 2 : 0;
    this.snake = [{ x: SPAWN.x, y: SPAWN.y }, { x: SPAWN.x - 1, y: SPAWN.y }, { x: SPAWN.x - 2, y: SPAWN.y }];
    this.prev = this.snake.map((s) => ({ ...s }));
    this.dir = 'right';
    this.queue = [];
    this.grow = 0;
    this.acc = 0;
    this.bulges = [];
    this.golden = null;
    this.lastEat = -99;
    this.fx.clear();
    this.popups.clear();
    this.food = this.#spawnFood();
    this.reveal = 0;
    this.readyT = 0;
    this.lastCount = -1;
    this.state = 'ready';
  }

  #speed() {
    const m = this.mode;
    const base = m.id === 'village' ? m.speed + 0.4 * (this.level - 1) : m.speed;
    return Math.min(m.maxSpeed, base + m.speedUp * this.levelApplesOrTotal());
  }
  levelApplesOrTotal() { return this.mode.id === 'village' ? this.levelApples : this.apples; }

  #occupied(x, y) {
    return this.snake.some((s) => s.x === x && s.y === y);
  }

  #spawnFood(avoid = null) {
    const head = this.snake[0];
    const near = [], far = [];
    for (let y = 0; y < ROWS; y++) for (let x = 0; x < COLS; x++) {
      const i = x + y * COLS;
      if (!this.reach[i] || this.solid[i] || this.#occupied(x, y)) continue;
      if (this.food && this.food.x === x && this.food.y === y) continue;
      if (avoid && avoid.x === x && avoid.y === y) continue;
      if (this.golden && this.golden.x === x && this.golden.y === y) continue;
      (Math.abs(x - head.x) + Math.abs(y - head.y) >= 4 ? far : near).push({ x, y });
    }
    const pool = far.length ? far : near;
    if (!pool.length) return null;
    const p = pool[(Math.random() * pool.length) | 0];
    this.fx.burst(p.x * TILE + 8, p.y * TILE + 8, { count: 8, colors: [C.white, C.mint], speed: 40, life: 0.35, gravity: 0 });
    return { ...p, born: this.time };
  }

  // ==========================================================================
  //  Input
  // ==========================================================================

  onButton(btn) {
    const a = this.api.audio;
    switch (this.state) {
      case 'title':
        if (btn === 'up' || btn === 'down') {
          this.modeIndex = (this.modeIndex + (btn === 'up' ? -1 : 1) + MODES.length) % MODES.length;
          a.play('move');
        } else if (btn === 'a' || btn === 'start') {
          a.play('select');
          this.#startRun();
        } else if (btn === 'b' || btn === 'select') {
          this.#buildTitleMap();
          a.play('move');
        }
        break;
      case 'ready':
      case 'play':
        if (DIRS[btn]) this.#queueTurn(btn);
        else if (btn === 'start') { this.pause(); a.play('pause'); }
        break;
      case 'paused':
        if (btn === 'start' || btn === 'a') { this.state = this.resumeState || 'play'; a.play('pause'); }
        else if (btn === 'b') { this.state = 'title'; this.#buildTitleMap(); a.play('back'); }
        break;
      case 'over':
        if (this.overT < 0.6) return; // don't skip the panel by accident
        if (btn === 'a' || btn === 'start') { a.play('select'); this.#startRun(); }
        else if (btn === 'b') { this.state = 'title'; this.#buildTitleMap(); a.play('back'); }
        break;
      case 'clear':
        if (this.clearT > 0.8 && (btn === 'a' || btn === 'start')) this.#nextLevel();
        break;
    }
  }

  #queueTurn(dir) {
    const last = this.queue.length ? this.queue[this.queue.length - 1] : this.dir;
    if (dir === last || dir === OPP[last] || this.queue.length >= 3) return;
    this.queue.push(dir);
  }

  // ==========================================================================
  //  Update
  // ==========================================================================

  update(dt) {
    this.time += dt;
    this.fx.update(dt);
    this.popups.update(dt);
    this.shake.update(dt);
    this.flash = Math.max(0, (this.flash || 0) - dt);

    // chimney smoke (ambient life)
    for (const c of this.chimneys) {
      c.t += dt;
      if (c.t > 0.9) { c.t = 0; this.fx.puff(c.x, c.y); }
    }

    switch (this.state) {
      case 'ready': return this.#updateReady(dt);
      case 'play': return this.#updatePlay(dt);
      case 'dying': return this.#updateDying(dt);
      case 'over': this.overT += dt; return;
      case 'clear':
        this.clearT += dt;
        if (this.clearT > 2.6) this.#nextLevel();
        return;
    }
  }

  #updateReady(dt) {
    if (this.reveal < 1) { this.reveal = Math.min(1, this.reveal + dt / 0.7); return; }
    this.readyT += dt;
    const count = 3 - Math.floor(this.readyT / 0.42);
    if (count !== this.lastCount) {
      this.lastCount = count;
      if (count > 0) this.api.audio.play('tick');
    }
    if (count <= 0) {
      this.state = 'play';
      this.goT = 0.5;
      this.api.audio.play('go');
    }
  }

  #updatePlay(dt) {
    this.goT = Math.max(0, (this.goT || 0) - dt);
    if (this.mode.time) {
      this.timeLeft -= dt;
      if (this.timeLeft <= 0) { this.timeLeft = 0; return this.#finish('time'); }
    }
    if (this.golden && this.time - this.golden.born > this.golden.life) {
      this.fx.burst(this.golden.x * TILE + 8, this.golden.y * TILE + 8, { count: 6, colors: [PAL.goldDark, C.dim], speed: 20 });
      this.golden = null;
    }
    if (this.golden && Math.random() < dt * 6) {
      this.fx.burst(this.golden.x * TILE + 2 + Math.random() * 12, this.golden.y * TILE + 2 + Math.random() * 10, { count: 1, colors: [C.white, C.gold], speed: 4, gravity: -10, life: 0.5, size: [1, 1] });
    }

    const step = 1 / this.#speed();
    this.acc += dt;
    while (this.acc >= step && this.state === 'play') {
      this.acc -= step;
      this.#tick();
    }
    this.bulges = this.bulges.map((b) => b + dt * this.#speed()).filter((b) => b < this.snake.length + 1);
  }

  #tick() {
    this.prev = this.snake.map((s) => ({ ...s }));
    if (this.queue.length) {
      const d = this.queue.shift();
      if (d !== OPP[this.dir]) { this.dir = d; this.api.audio.play('turn'); }
    }
    const [dx, dy] = DIRS[this.dir];
    const head = this.snake[0];
    let nx = head.x + dx, ny = head.y + dy;
    if (this.mode.wrap) {
      nx = (nx + COLS) % COLS;
      ny = (ny + ROWS) % ROWS;
    } else if (nx < 0 || ny < 0 || nx >= COLS || ny >= ROWS) {
      return this.#die('wall');
    }
    const ni = nx + ny * COLS;
    if (this.solid[ni]) return this.#die(this.map.kinds[ny][nx]);

    const willPop = this.grow === 0;
    const bodyLen = willPop ? this.snake.length - 1 : this.snake.length;
    for (let i = 0; i < bodyLen; i++) {
      if (this.snake[i].x === nx && this.snake[i].y === ny) return this.#die('self');
    }

    this.snake.unshift({ x: nx, y: ny });
    if (willPop) this.snake.pop(); else this.grow--;

    if (this.food && nx === this.food.x && ny === this.food.y) this.#eat(false);
    else if (this.golden && nx === this.golden.x && ny === this.golden.y) this.#eat(true);
  }

  #eat(golden) {
    const a = this.api.audio;
    const cell = golden ? this.golden : this.food;
    const cx = cell.x * TILE + 8, cy = cell.y * TILE + 8;

    this.combo = this.time - this.lastEat < 3.5 ? Math.min(this.combo + 1, 8) : 1;
    this.lastEat = this.time;
    const pts = (golden ? 50 : 10) * this.combo;
    this.score += pts;
    this.grow += golden ? 2 : 1;
    this.apples++;
    this.levelApples++;
    this.bulges.push(0);
    bumpStat('snake:apples');

    const colors = golden ? [PAL.gold, PAL.goldLight, C.white] : [PAL.apple, PAL.appleLight, PAL.leafLight, C.white];
    this.fx.burst(cx, cy, { count: golden ? 26 : 16, colors, speed: golden ? 110 : 80, life: 0.55, gravity: 160, up: 30 });
    this.popups.add(this.combo > 1 ? `+${pts} x${this.combo}` : `+${pts}`, cx, cy - 10, golden ? C.gold : C.white);
    this.shake.add(golden ? 3 : 1, 0.15);
    this.api.vibrate(golden ? 25 : 12);

    if (golden) {
      a.play('golden');
      if (this.mode.time) { this.timeLeft += 5; this.popups.add('+5 SEC', W / 2, 40, C.mint, 1.2); }
      this.golden = null;
    } else {
      a.play(this.combo >= 3 ? 'combo' : 'eat');
      this.food = this.#spawnFood({ x: cell.x, y: cell.y });
      if (!this.golden && this.apples > 2 && Math.random() < 0.2) {
        const g = this.#spawnFood();
        if (g) { this.golden = { ...g, life: 7 }; a.play('spawnGolden'); }
      }
      if (!this.food) return this.#finish('perfect');
    }

    if (this.mode.id === 'village' && this.levelApples >= this.goal) {
      const bonus = 50 * this.level;
      this.score += bonus;
      this.clearBonus = bonus;
      this.clearT = 0;
      this.state = 'clear';
      a.play('levelup');
    }
  }

  #nextLevel() {
    this.level++;
    this.#startLevel();
  }

  #die(cause) {
    this.cause = cause;
    this.state = 'dying';
    this.dieT = 0;
    this.popIndex = 0;
    this.flash = 0.08;
    this.shake.add(5, 0.45);
    this.api.audio.play('die');
    this.api.vibrate([40, 30, 60]);
  }

  #updateDying(dt) {
    this.dieT += dt;
    if (this.dieT < 0.45) return; // freeze on impact
    const target = Math.floor((this.dieT - 0.45) / 0.035);
    while (this.popIndex < Math.min(target, this.snake.length)) {
      const s = this.snake[this.popIndex];
      this.fx.burst(s.x * TILE + 8, s.y * TILE + 8, { count: 6, colors: [C.body, C.spot, C.shine], speed: 70, life: 0.5, gravity: 200, up: 40 });
      if (this.popIndex % 2 === 0) this.api.audio.play('pop');
      this.popIndex++;
    }
    if (this.popIndex >= this.snake.length && this.dieT > 0.45 + this.snake.length * 0.035 + 0.4) this.#finish('dead');
  }

  #finish(reason) {
    this.endReason = reason;
    this.newBest = submitScore('snake', this.mode.id, this.score);
    this.best = getBest('snake', this.mode.id);
    this.state = 'over';
    this.overT = 0;
    if (reason !== 'dead') this.api.audio.play('levelup');
    if (this.newBest && this.score > 0) setTimeout(() => this.api.audio.play('record'), reason === 'dead' ? 200 : 700);
  }

  // ==========================================================================
  //  Rendering
  // ==========================================================================

  render() {
    const g = this.ctx;
    // how far we are between the last two movement ticks (smooth sliding)
    const alpha = this.state === 'play' ? Math.min(1, this.acc * this.#speed()) : 1;
    const [sx, sy] = this.shake.offset();
    g.save();
    g.translate(sx, sy + HUD);

    this.#drawMap(g);
    if (this.state !== 'title') {
      this.#drawFood(g);
      if (this.state !== 'over') {
        // keep the last interpolated pose when paused / between levels (no jump-back)
        const a = this.state === 'play' ? (this.lastAlpha = alpha) : this.state === 'ready' ? 0 : this.state === 'dying' ? 1 : (this.lastAlpha ?? 1);
        this.#drawSnake(g, a);
      }
    }
    this.fx.draw(g);
    this.popups.draw(g);
    g.restore();

    if (this.flash > 0) { g.fillStyle = C.white; g.fillRect(0, 0, W, H); }
    this.#drawHud(g);

    switch (this.state) {
      case 'title': this.#drawTitle(g); break;
      case 'ready': this.#drawReady(g); break;
      case 'play': if (this.goT > 0) this.#bigText(g, 'GO!', C.mint); break;
      case 'paused': this.#drawPaused(g); break;
      case 'over': this.#drawOver(g); break;
      case 'clear': this.#drawClear(g); break;
    }
  }

  #drawMap(g) {
    if (this.reveal >= 1) { g.drawImage(this.bg, 0, 0); return; }
    // Reveal the arena in the exact order WFC collapsed it.
    g.fillStyle = C.gb0;
    g.fillRect(0, 0, W, H - HUD);
    const order = this.map.order;
    const n = Math.floor(order.length * this.reveal);
    for (let k = 0; k < n; k++) {
      const i = order[k];
      const x = (i % COLS) * TILE, y = ((i / COLS) | 0) * TILE;
      g.drawImage(this.bg, x, y, TILE, TILE, x, y, TILE, TILE);
    }
  }

  #drawFood(g) {
    const spr = sprites();
    if (this.food) {
      const age = this.time - this.food.born;
      const bob = Math.round(Math.sin(this.time * 5) * 1);
      if (age < 0.15) {
        // pop-in: small then full size
        g.drawImage(spr.apple, 4, 4, 8, 8, this.food.x * TILE + 4, this.food.y * TILE + 4, 8, 8);
      } else {
        g.drawImage(spr.apple, this.food.x * TILE, this.food.y * TILE + bob);
      }
    }
    if (this.golden) {
      const left = this.golden.life - (this.time - this.golden.born);
      const blink = left < 2 && ((this.time * 10) | 0) % 2;
      if (!blink) g.drawImage(spr.golden, this.golden.x * TILE, this.golden.y * TILE + Math.round(Math.sin(this.time * 7)));
    }
  }

  /** Snake body as a thick axis-aligned polyline through interpolated segment centres. */
  #drawSnake(g, alpha) {
    const s = this.snake;
    const n = s.length;
    const popped = this.state === 'dying' ? this.popIndex : 0;
    if (popped >= n) return;

    const lerp = (i) => {
      const a = this.prev[i] || s[i], b = s[i];
      if (Math.abs(a.x - b.x) > 1 || Math.abs(a.y - b.y) > 1) return { x: b.x * TILE + 8, y: b.y * TILE + 8 }; // wrapped
      return {
        x: Math.round((a.x + (b.x - a.x) * alpha) * TILE + 8),
        y: Math.round((a.y + (b.y - a.y) * alpha) * TILE + 8),
      };
    };
    const P = s.map((_, i) => lerp(i));
    const corner = (i) => ({ x: s[i].x * TILE + 8, y: s[i].y * TILE + 8 }); // = prev[i-1]
    const half = (i) => (i >= n - 1 && n > 3 ? 4 : i >= n - 2 && n > 3 ? 5 : 6);

    const legs = [];
    for (let i = popped; i < n - 1; i++) {
      const c = corner(i + 1);
      legs.push([P[i], c, half(i)], [c, P[i + 1], half(i + 1)]);
    }
    const rect = (a, b, h) => {
      if (Math.abs(a.x - b.x) > TILE || Math.abs(a.y - b.y) > TILE) return;
      const x0 = Math.min(a.x, b.x) - h, y0 = Math.min(a.y, b.y) - h;
      g.fillRect(x0, y0, Math.abs(a.x - b.x) + h * 2, Math.abs(a.y - b.y) + h * 2);
    };

    // 1) outline
    g.fillStyle = C.bodyInk;
    for (const [a, b, h] of legs) rect(a, b, h + 1);
    for (const bIdx of this.bulges) { const i = Math.floor(bIdx); if (i >= popped && i < n) rect(P[i], P[i], 8); }
    if (n - popped === 1) rect(P[popped], P[popped], 7);
    // 2) body fill
    g.fillStyle = C.body;
    for (const [a, b, h] of legs) rect(a, b, h);
    for (const bIdx of this.bulges) { const i = Math.floor(bIdx); if (i >= popped && i < n) rect(P[i], P[i], 7); }
    // 3) pattern: spots + shine travel with the segments
    for (let i = Math.max(1, popped); i < n; i++) {
      const p = P[i];
      if (i % 2 === 0) { g.fillStyle = C.spot; g.fillRect(p.x - 2, p.y - 2, 4, 4); }
      else if (half(i) >= 5) { g.fillStyle = C.shine; g.fillRect(p.x - 4, p.y - 4, 2, 2); }
    }
    // 4) head
    if (popped === 0) this.#drawHead(g, P[0]);
  }

  #drawHead(g, p) {
    const [fx, fy] = DIRS[this.dir];
    const sx = -fy, sy = fx; // side vector
    // rounded 16x16 head
    g.fillStyle = C.bodyInk;
    g.fillRect(p.x - 8, p.y - 7, 16, 14);
    g.fillRect(p.x - 7, p.y - 8, 14, 16);
    g.fillStyle = C.body;
    g.fillRect(p.x - 7, p.y - 6, 14, 12);
    g.fillRect(p.x - 6, p.y - 7, 12, 14);
    g.fillStyle = C.shine;
    g.fillRect(p.x - 5, p.y - 5, 3, 2);

    const dead = this.state === 'dying';
    for (const side of [-1, 1]) {
      const ex = p.x + fx * 2 + sx * 3 * side;
      const ey = p.y + fy * 2 + sy * 3 * side;
      if (dead) {
        g.fillStyle = C.bodyInk;
        for (let k = -1; k <= 1; k++) { g.fillRect(ex + k - 1, ey + k - 1, 2, 2); g.fillRect(ex + k - 1, ey - k - 1, 2, 2); }
      } else {
        const blink = (this.time % 3.2) < 0.12;
        g.fillStyle = C.white;
        if (blink) g.fillRect(ex - 2, ey, 4, 1);
        else {
          g.fillRect(ex - 2, ey - 2, 4, 4);
          g.fillStyle = C.bodyInk;
          g.fillRect(ex - 1 + Math.max(0, fx), ey - 1 + Math.max(0, fy), 2, 2);
        }
      }
    }
    // flicking tongue
    if (!dead && (this.time % 2.4) < 0.22) {
      g.fillStyle = C.red;
      const tx = p.x + fx * 8, ty = p.y + fy * 8;
      if (fx) { g.fillRect(fx > 0 ? tx : tx - 3, ty, 3, 1); g.fillRect(tx + fx * 3, ty - 1, 1, 1); g.fillRect(tx + fx * 3, ty + 1, 1, 1); }
      else { g.fillRect(tx, fy > 0 ? ty : ty - 3, 1, 3); g.fillRect(tx - 1, ty + fy * 3, 1, 1); g.fillRect(tx + 1, ty + fy * 3, 1, 1); }
    }
  }

  // ---- HUD & overlays ----------------------------------------------------------

  #drawHud(g) {
    g.fillStyle = C.hudBg;
    g.fillRect(0, 0, W, HUD);
    g.fillStyle = C.gb1;
    g.fillRect(0, HUD - 1, W, 1);
    if (this.state === 'title') {
      drawText(g, 'PIXEL HUB', 6, 4, { color: C.gb3 });
      drawText(g, this.api.settings.daily ? 'DAILY MAPS' : 'RANDOM MAPS', W - 6, 4, { color: C.dim, align: 'right' });
      return;
    }
    const best = Math.max(getBest('snake', this.mode.id), this.score || 0);
    drawText(g, String(this.score).padStart(6, '0'), 6, 4, { color: C.white });
    if (this.combo > 1 && this.time - this.lastEat < 3.5 && this.state === 'play') {
      drawText(g, `x${this.combo}`, 60, 4, { color: C.gold });
    }
    // middle: mode-specific
    const mid = W / 2;
    if (this.mode.time) {
      const t = Math.ceil(this.timeLeft);
      const warn = t <= 10 && ((this.time * 4) | 0) % 2;
      drawText(g, `${t}s`, mid - 30, 4, { color: warn ? C.red : C.mint, align: 'right' });
      const bw = 56, frac = Math.min(1, this.timeLeft / this.mode.time);
      g.fillStyle = C.gb0; g.fillRect(mid - 24, 5, bw, 6);
      g.fillStyle = t <= 10 ? C.red : C.gb3; g.fillRect(mid - 23, 6, Math.round((bw - 2) * frac), 4);
    } else if (this.mode.id === 'village') {
      drawText(g, `LV${this.level}`, mid - 34, 4, { color: C.mint });
      g.drawImage(sprites().apple, 2, 2, 12, 12, mid + 2, 2, 12, 12);
      drawText(g, `${Math.min(this.levelApples, this.goal)}/${this.goal}`, mid + 16, 4, { color: C.white });
    } else {
      g.drawImage(sprites().apple, 2, 2, 12, 12, mid - 22, 2, 12, 12);
      drawText(g, `${this.snake?.length ?? 0}`, mid - 6, 4, { color: C.white });
    }
    drawText(g, `HI ${String(best).padStart(6, '0')}`, W - 6, 4, { color: C.gb3, align: 'right' });
  }

  #makeDither() {
    const c = document.createElement('canvas');
    c.width = 2; c.height = 2;
    const g = c.getContext('2d');
    g.fillStyle = '#0c140e';
    g.fillRect(0, 0, 1, 1);
    g.fillRect(1, 1, 1, 1);
    return this.ctx.createPattern(c, 'repeat');
  }

  #dim(g, y = HUD, h = H - HUD) {
    g.fillStyle = this.dither;
    g.fillRect(0, y, W, h);
  }

  #panel(g, x, y, w, h) {
    g.fillStyle = C.ink;
    g.fillRect(x + 1, y, w - 2, h);
    g.fillRect(x, y + 1, w, h - 2);
    g.fillStyle = C.gb3;
    g.fillRect(x + 2, y + 1, w - 4, h - 2);
    g.fillRect(x + 1, y + 2, w - 2, h - 4);
    g.fillStyle = C.gb0;
    g.fillRect(x + 3, y + 3, w - 6, h - 6);
    g.fillStyle = C.gb1;
    g.fillRect(x + 3, y + 3, w - 6, 1);
  }

  #bigText(g, text, color) {
    drawText(g, text, W / 2, H / 2 - 12, { size: 24, color, align: 'center', outline: C.ink });
  }

  #drawTitle(g) {
    this.#dim(g);
    const t = this.time;
    // logo
    const bounce = Math.round(Math.sin(t * 2.2) * 2);
    drawText(g, 'SNAKE', W / 2 + 3, 34 + bounce + 3, { size: 32, color: C.gb0, align: 'center' });
    drawText(g, 'SNAKE', W / 2, 34 + bounce, { size: 32, color: C.body, align: 'center', outline: C.bodyInk });
    drawText(g, 'VILLAGE EDITION', W / 2, 76, { color: C.mint, align: 'center', shadow: C.ink });
    g.drawImage(sprites().apple, W / 2 + 84, 30 + Math.round(Math.sin(t * 3 + 1) * 2));

    // mode menu
    const x = 44, y = 100, w = 232, rowH = 20;
    this.#panel(g, x, y, w, rowH * MODES.length + 12);
    MODES.forEach((m, i) => {
      const ry = y + 8 + i * rowH;
      const sel = i === this.modeIndex;
      if (sel) {
        g.fillStyle = C.gb1;
        g.fillRect(x + 6, ry - 2, w - 12, rowH - 4);
        if (((t * 3) | 0) % 2 === 0) this.#arrow(g, x + 11, ry + 3, C.gold);
      }
      drawText(g, m.name, x + 24, ry + 2, { color: sel ? C.white : C.gb2 });
      const best = getBest('snake', m.id);
      drawText(g, best ? String(best).padStart(5, '0') : '-----', x + w - 12, ry + 2, { color: sel ? C.gold : C.gb1, align: 'right' });
    });
    const dy = y + rowH * MODES.length + 22;
    this.mode.desc.forEach((line, i) => drawText(g, line, W / 2, dy + i * 12, { color: C.white, align: 'center', shadow: C.ink }));

    if (((t * 2) | 0) % 2 === 0) drawText(g, 'PRESS START', W / 2, H - 34, { color: C.gold, align: 'center', outline: C.ink });
    drawText(g, 'B: NEW VILLAGE', W / 2, H - 16, { color: C.mint, align: 'center', outline: C.ink });
  }

  #arrow(g, x, y, color) {
    g.fillStyle = color;
    for (let i = 0; i < 4; i++) g.fillRect(x + i, y + i, 1, 8 - i * 2);
  }

  #drawReady(g) {
    if (this.reveal < 1) {
      drawText(g, 'GENERATING VILLAGE', W / 2, H - 22, { color: C.white, align: 'center', outline: C.ink });
      return;
    }
    const count = Math.max(1, 3 - Math.floor(this.readyT / 0.42));
    this.#bigText(g, String(count), C.gold);
    const label = this.mode.id === 'village' ? `${this.mode.name} ${this.level}` : this.mode.name;
    drawText(g, label, W / 2, H / 2 + 22, { color: C.white, align: 'center', outline: C.ink });
    if (this.mode.id === 'village') drawText(g, `EAT ${this.goal} APPLES`, W / 2, H / 2 + 36, { color: C.mint, align: 'center', outline: C.ink });
    drawText(g, `SEED ${this.seedText}`, W / 2, H - 14, { color: C.white, align: 'center', outline: C.ink });
  }

  #drawPaused(g) {
    this.#dim(g);
    const w = 180, h = 84, x = (W - w) / 2, y = 100;
    this.#panel(g, x, y, w, h);
    drawText(g, 'PAUSED', W / 2, y + 14, { size: 16, color: C.white, align: 'center' });
    drawText(g, 'START  RESUME', W / 2, y + 44, { color: C.gb3, align: 'center' });
    drawText(g, 'B      MENU  ', W / 2, y + 60, { color: C.gb2, align: 'center' });
  }

  #drawOver(g) {
    this.#dim(g);
    const t = this.overT;
    const w = 236, h = 168, x = (W - w) / 2;
    const y = Math.round(58 + Math.max(0, 1 - t * 4) * -200); // drop in
    this.#panel(g, x, y, w, h);
    const title = this.endReason === 'time' ? "TIME'S UP!" : this.endReason === 'perfect' ? 'PERFECT!' : 'GAME OVER';
    drawText(g, title, W / 2, y + 14, { size: 16, color: this.endReason === 'dead' ? C.red : C.gold, align: 'center' });
    const causes = { wall: 'BONK! HIT THE WALL', self: 'OUCH! BIT YOURSELF', house: 'CRASHED INTO A HOUSE', tree: 'TANGLED IN A TREE' };
    if (this.endReason === 'dead') drawText(g, causes[this.cause] || '', W / 2, y + 36, { color: C.dim, align: 'center' });

    const rows = [['SCORE', this.score], ['BEST', this.best], ['LENGTH', this.snake.length]];
    if (this.mode.id === 'village') rows.push(['VILLAGE', this.level]);
    else rows.push(['APPLES', this.apples]);
    rows.forEach(([k, v], i) => {
      const ry = y + 54 + i * 14;
      drawText(g, k, x + 20, ry, { color: C.gb2 });
      drawText(g, String(v), x + w - 20, ry, { color: C.white, align: 'right' });
    });
    if (this.newBest && this.score > 0 && ((this.time * 4) | 0) % 2 === 0) {
      drawText(g, 'NEW BEST!', W / 2, y + 112, { color: C.gold, align: 'center' });
    }
    drawText(g, `SEED ${this.seedText}`, W / 2, y + 128, { color: C.gb1, align: 'center' });
    if (t > 0.6) drawText(g, 'A RETRY   B MENU', W / 2, y + 146, { color: C.white, align: 'center' });
  }

  #drawClear(g) {
    this.#dim(g);
    const w = 236, h = 92, x = (W - w) / 2, y = 96;
    this.#panel(g, x, y, w, h);
    drawText(g, 'VILLAGE CLEAR!', W / 2, y + 16, { size: 16, color: C.gold, align: 'center' });
    drawText(g, `BONUS +${this.clearBonus}`, W / 2, y + 44, { color: C.white, align: 'center' });
    if (((this.time * 3) | 0) % 2 === 0) drawText(g, 'NEXT VILLAGE...', W / 2, y + 66, { color: C.mint, align: 'center' });
  }
}
